    const malformedOwner: Record<string, unknown> = { format: "future-lock", formatVersion: 2, operationId: "bad operation", identityKind: "invalid-kind", identityKey: "", nonce: "z".repeat(32), generation: "z".repeat(32), pid: 0, processToken: "", acquiredAt: "not-a-time", heartbeatAt: "not-a-time" };
